    "context": "【原問の対話：先行する発言には誤った解答も含まれます】\n第12問       次の対話は、書面による登記の申請の代理に関する教授と学生の対話である。教授の\n    質問に対する次のアからオまでの学生の解答のうち、誤っているものの組合せは、後記\n       １ から ５ までのうち、どれか。\n    教授：       Ａが所有権の登記名義人である甲土地について、Ａの単独親権者であるＢが法\n             定代理人として所有権の移転の登記の申請をしようとしたが、その申請前にＡが\n             死亡した場合には、Ｂの当該申請に関する代理権は、どうなりますか。\n    学生：ア         その代理権は消滅しません。\n    教授：       それでは、Ａが所有権の登記名義人である甲土地について、Ａの成年後見人で\n             あるＢが法定代理人として司法書士Ｃに対してＡからＤへの所有権の移転の登記\n             の申請を委任したが、その後、Ｂが破産手続開始の決定を受けた場合には、Ｃ\n             は、当該申請の添付情報として、誰の印鑑に関する証明書を提供しなければなり\n             ませんか。\n    学生：イ         Ｂの印鑑に関する証明書を提供しなければなりません。\n    教授：       当該申請の添付情報として提供する印鑑に関する証明書は、作成後 ３ か月以内\n             のものであることを要しますか。\n    学生：ウ         作成後 ３ か月以内のものであることを要します。\n    教授：       事例を変えて、Ａが唯一の代表者である会社法人等番号を有するＢ法人が所有\n             権の登記名義人である甲土地について、ＡがＢ法人を代表して司法書士Ｃに対し\n             てＢ法人からＤへの所有権の移転の登記の申請を委任したが、当該申請前にＡが\n             Ｂ法人の代表者を辞任し、新しい代表者としてＥが就任したとします。この場合\n             において、当該登記申請の添付情報としてＢ法人の会社法人等番号を提供するこ\n             ととなりますが、それだけではＡが代表者であったことが確認できないときは、\n             添付情報として何を提供すべきですか。\n    学生：エ 登記申請の委任を受けた当時にＡが代表者であったことが確認できるＢ法人\n              の登記事項証明書を提供しなければなりません。\n    教授：       最後に、Ａが所有権の登記名義人である甲土地について、Ａが司法書士Ｂ及び\n             司法書士Ｃに対してＡからＤへの所有権の移転の登記の申請を委任したが、特に\n             共同代理の定めがされていない場合には、Ｂ及びＣを代理人とする代理権限を証\n             する情報を提供して、Ｃのみが当該申請を代理することはできますか。",
