    "context": "【原問の対話：先行する発言には誤った解答も含まれます】\n第14問       次の対話は、権利能力なき社団であるＡ社団の構成員全員に総有的に帰属する甲土地\n    の所有権の登記名義人がＡ社団の代表者Ｂである場合に関する教授と学生の対話であ\n    る。教授の質問に対する次のアからオまでの学生の解答のうち、正しいものの組合せ\n       は、後記 １ から ５ までのうち、どれか。\n       教授：    Ａ社団の代表者としてＣが追加して選任された場合には、Ｂ及びＣが申請する\n             ＢからＣへの所有権の一部移転の登記の登記原因は何ですか。\n       学生：ア 「委任の変更」となります。\n       教授：       次に、Ｂが死亡し、後日、Ａ社団の代表者としてＣが就任したという事例を\n            「本件事例」としましょう。本件事例において、ＣがＡ社団の代表者に就任した\n             ことにより、甲土地についてＢからＣへの所有権の移転の登記を申請する場合に\n             は、その登記原因の日付はいつになりますか。\n       学生：イ      Ｂが死亡した日となります。\n       教授：    本件事例において、Ａ社団の代表者としてＣが就任したため、甲土地について\n             ＢからＣへの所有権の移転の登記を申請しようとしたが、その申請をする前に、\n             Ｂの相続人であるＤが相続を原因とするＢからＤへの所有権の移転の登記を申請\n             し、その旨の登記がされていたとします。この場合には、Ｃは、どのような登記\n             の申請をすることとなりますか。\n       学生：ウ Ｃは、ＢからＤへの所有権の移転の登記の抹消の申請をしなくても、Ｄから\n              Ｃへの委任の終了を原因とする所有権の移転の登記の申請をすることができま\n              す。\n       教授：    本件事例において、甲土地についてＢからＣへの所有権の移転の登記を申請す\n             る前に、Ｃは、Ａ社団を代表して甲土地をＥに売却したとします。この場合に\n             は、Ｃ及びＥは、売買を原因とするＢからＥへの所有権の移転の登記を申請する\n             ことはできますか。\n       学生：エ      いいえ、できません。\n       教授：    最後に、事例を変えて、Ａ社団がＦから金銭を借り入れ、その貸金債権を担保\n             するためにＦを抵当権者とする抵当権が甲土地に設定されたとします。当該抵当\n             権の設定の登記を申請する場合には、債務者としてＡ社団の名称を申請情報の内\n             容とすることはできますか。",
